import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), g = nextInt(), k = nextInt();
        double[] scores = new double[n];
        for (int i = 0; i < n; i++) scores[i] = Double.parseDouble(next());
        StringBuilder out = new StringBuilder().append(g).append('\n');
        MathContext digits = new MathContext(12);
        for (int t = 0; t < g; t++) {
            int m = nextInt();
            double[] values = new double[m];
            for (int i = 0; i < m; i++) values[i] = scores[nextInt()];
            Arrays.sort(values);
            double sum = 0;
            for (int i = 0; i < k; i++) sum += values[m - 1 - i]; // the k highest, largest first
            if (t > 0) out.append(' ');
            out.append(new BigDecimal(sum).round(digits).stripTrailingZeros().toPlainString());
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, g, k := int(nextInt()), int(nextInt()), int(nextInt())
	scores := make([]float64, n)
	for i := range scores {
		scores[i], _ = strconv.ParseFloat(string(next()), 64)
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(g) + "\n")
	for t := 0; t < g; t++ {
		m := int(nextInt())
		values := make([]float64, m)
		for i := range values {
			values[i] = scores[nextInt()]
		}
		sort.Sort(sort.Reverse(sort.Float64Slice(values))) // the k highest come first
		sum := 0.0
		for _, v := range values[:k] {
			sum += v
		}
		if t > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatFloat(sum, 'g', 12, 64))
	}
	w.WriteByte('\n')
}
